import logging
from taf.collectors.core import ManagedObject
from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core import StartableCollector
from taf.sbts.browser_server.facade import Client

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class BrowserServer(ManagedObject):
    """
    Adapter for 3G Browser Server client (taf.sbts.browser_server).

    Shared by L2Trace3GCollector and CellThroughputCollector.
    """

    def __init__(self,
                 bts_host='192.168.255.129',
                 bts_port=15003,
                 enable_extra_log=False,
                 **kwargs):
        super(BrowserServer, self).__init__(**kwargs)
        self._bts_host = bts_host
        self._bts_port = bts_port
        self._enable_extra_log = enable_extra_log
        self._client = Client()

    def __getattr__(self, name):
        return getattr(self._client, name)

    def _setup(self):
        self._client.set_up(bts_host=self._bts_host,
                            bts_port=self._bts_port,
                            enable_extra_log=self._enable_extra_log)

    def _teardown(self):
        self._client.tear_down()


class BrowserServerCollectorBase(Using("file_getter"), StartableCollector):
    """
    Base class for `CellThroughputCollector` and `L2Trace3GCollector`.
    """

    def __init__(self,
                 tool,
                 cell_id,
                 as_zip=True,
                 **kwargs):
        super(BrowserServerCollectorBase, self).__init__(**kwargs)
        self._tool = tool
        self._cell_id = cell_id
        self._as_zip = as_zip
        self.add_prerequisite(self._tool)

    def _stop(self):
        self._tool.stop_trace()

    def _collect(self, target_dir):
        """
        Transfer the information, that shall be collected, from the remote host to the local host.

        :param str target_dir: target path, where collected information shall be stored on the local host
        """
        target_path = "{target_dir}/{target_file_name}".format(
            target_dir=target_dir,
            target_file_name=self._target_file_name)
        logger.debug(
            "collecting to {target_path!r}".format(
                target_path=target_path))
        self._tool.save_trace(output_path=target_path,
                              as_zip=self._as_zip)


class CellThroughputCollector(BrowserServerCollectorBase):
    """
    Generation of a CellThroughput 3G is triggered via browser server client and the result is stored locally in
    the directory target_dir, that is given to the collect() call.
    """

    def __init__(self,
                 target_file_name=None,
                 **kwargs):
        super(CellThroughputCollector, self).__init__(**kwargs)
        if target_file_name is None:
            target_file_name = "cell_throughput.zip"
        self._target_file_name = target_file_name

    def _start(self):
        self._tool.start_cell_throughput(cell_id=self._cell_id)


class L2Trace3GCollector(BrowserServerCollectorBase):
    """
    Generation of a L2stream 3G is triggered via browser server client and the result is stored locally in
    the directory target_dir, that is given to the collect() call.
    """

    def __init__(self,
                 target_file_name=None,
                 **kwargs):
        super(L2Trace3GCollector, self).__init__(**kwargs)
        if target_file_name is None:
            target_file_name = "l2trace_3g.zip"
        self._target_file_name = target_file_name

    def _start(self):
        self._tool.start_hsupa_l2_trace(cell_id=self._cell_id)
